function s4Unlocked(){try{if(saveData.s4open)return true;const stars=hfData().slice(0,30);return stars.length===30&&stars.every(x=>x.rk)}catch(e){return false}}
function s4Sv(){const s=saveData.ch4=saveData.ch4||{};s.ci=s.ci||0;s.best=s.best||{};return s}
function s4Info(){const s=s4Sv(),slots=S4.map((b,k)=>({k,art:b.art,name:b.name,rank:s.best[k]||null,seen:k<s.ci,cur:k===s.ci}));return {slots,done:s.ci>=10,prog:Math.min(1,s.ci/10)}}
