function scPrologue(){const cons=[[90,86,90,0],[240,70,96,1],[390,90,90,2]];const L4=window.__S4||[];
 const drawCons=(c,T,a,link)=>{for(const [x,y,sz,ch] of cons){const C=HF_CON[ch],P=C.pts.map(p=>[x+(p[0]-.5)*sz,y+(p[1]-.5)*sz]);if(link>0)for(const [i,j] of C.edges){const q=scCl(link*1.5-((i+j)%10)*.05);c.strokeStyle=C.col;c.globalAlpha=a*.5;c.beginPath();c.moveTo(P[i][0],P[i][1]);c.lineTo(P[i][0]+(P[j][0]-P[i][0])*q,P[i][1]+(P[j][1]-P[i][1])*q);c.stroke()}
  P.forEach((p,k)=>{const on=scCl(T*1.6-k*.12-ch*.4);if(on>0){scGlow(c,p[0],p[1],8,C.col,a*on);scSpark(c,p[0],p[1],2,'#fff',a*on)}})}c.globalAlpha=1};
 return [
  {d:4200,lines:[['','명예의 전당에 별 서른 개가 모두 켜진 밤.'],['','시계골의 하늘은 그 어느 때보다 밝았다.']],la:900,on(){try{stopMusic();[0,7,12,16].forEach((d,i)=>voice('bell',64+d,1.2,.02,audio.currentTime+i*.4))}catch(e){}},draw(c,T){scSky(c,T,'#03030c','#1a1030',1,170);drawCons(c,T,1,scCl((T-1.5)/2));scTown(c,T,.4)}},
  {d:3400,lines:[['똑딱','하루… 저기 봐. 별자리 가운데가… 갈라지고 있어.']],la:700,on(){try{sfx(80,2.4,'sine',.07,40)}catch(e){}},draw(c,T){scSky(c,T,'#03030c','#1a1030',1,170);drawCons(c,T+5,1-scCl(T/3)*.5,1);
   const q=scCl(T/2.6);c.strokeStyle='#e8e0ff';c.lineWidth=1;c.beginPath();let x=240,y=20;c.moveTo(x,y);const r=rng(hash('crack'));for(let i=0;i<9*q;i++){x+=(r()-.5)*24;y+=10;c.lineTo(x,y)}c.stroke();scGlow(c,240,60,30*q,'#c8a0ff',q);scTown(c,T,.4);if(q>.8)SC4.shake=Math.max(SC4.shake,.25)}},
  {d:4800,lines:[['','하늘이 갈라지고, 검은 해가 떠올랐다.'],['','그리고 별들이… 떨어지기 시작했다.']],la:600,on(){try{sfx(50,3,'sawtooth',.1,24);perc('crash',audio.currentTime,.7)}catch(e){}SC4.shake=.8},draw(c,T){scSky(c,T,'#08040e','#2a1030',2,90);const q=scE(T/2),ex=240,ey=110-q*30;scGlow(c,ex,ey,70*q,'#ffd98a',q);c.fillStyle='#fff0c8';c.beginPath();c.arc(ex,ey,34*q,0,TAU);c.fill();c.fillStyle='#05040a';c.beginPath();c.arc(ex+3,ey,33*q,0,TAU);c.fill();
   if(q>.5){const t2=T-1;scMeteors(c,t2,10,'#ffd8a8',.55)}scTown(c,T,.7);if(T>2&&Math.random()<.05)SC4.shake=Math.max(SC4.shake,.3)}},
  {d:3000,lines:[['똑딱','별의 수호자들이 깨어났어… 열 개의 빛이 전부 우리 마을로 오고 있어!']],la:500,draw(c,T){scSky(c,T,'#08040e','#2a1030',3,110);scMeteors(c,T,6,'#ffd8a8',.4);c.fillStyle='#06050c';c.fillRect(170,190,140,80);c.fillRect(160,184,160,8);scHero(c,240,183,3,T,true);try{drawTick(c,270,150+Math.sin(T*3)*3,performance.now(),1.4)}catch(e){}c.fillStyle='#030208';c.fillRect(0,SCH-14,SCW,14)}},
  {d:4200,on(){try{L4.forEach((b,i)=>voice('bell',60+i*2,.3,.02,audio.currentTime+.2+i*.3))}catch(e){}},draw(c,T){scSky(c,T,'#050208','#1a0a20',5,90);for(let i=0;i<10;i++){const t0=.2+i*.3,q=(T-t0);if(q<0)continue;const b=L4[i],x=40+(i%5)*100,y=i<5?120:220,a=Math.min(1,q*3)*(q>1.4?Math.max(.25,1-(q-1.4)):1);scGlow(c,x,y-30,34,b.c,a*.8);c.globalAlpha=a;const off=scSil(b.art);c.drawImage(off,Math.round(x-60),Math.round(y-100));c.globalAlpha=1}
   if(T>3.4){const q=scCl((T-3.4)/.6);scFlash(c,q*.9,'#000')}}},
  {d:3400,lines:[['???','……작은 박동이여. 별의 끝까지… 올라오너라.']],la:300,on(){try{sfx(40,3,'sine',.12,30)}catch(e){}},draw(c,T){c.fillStyle='#000';c.fillRect(0,0,SCW,SCH);const q=scE(T/1.4);const ex=240,ey=130;scGlow(c,ex,ey,90*q,'#fff4c8',q*.7);c.fillStyle='#fff4c8';c.beginPath();c.ellipse(ex,ey,60*q,Math.max(.5,14*q*(Math.sin(T*.8)>-.95?1:.1)),0,0,TAU);c.fill();c.fillStyle='#1a1a2a';c.beginPath();c.arc(ex,ey,10*q,0,TAU);c.fill();c.fillStyle='#8ae8ff';c.beginPath();c.arc(ex,ey,5*q,0,TAU);c.fill()}},
  {d:3600,on(){try{perc('crash',audio.currentTime,.8);[0,4,7,11,14].forEach((d,i)=>voice('bell',72+d,1,.03,audio.currentTime+i*.1))}catch(e){}SC4.shake=.6},draw(c,T){scSky(c,T,'#03030c','#1a1030',6,200);const q=scE(T/.8);scGlow(c,240,120,120*q,'#c8a0ff',.6);scFlash(c,Math.max(0,1-T*2));
   scTxt(c,'C H A P T E R   4',240,96,10,'#c8a0ff',q);scTxt(c,'ECLIPSE',240,136,40,'#ffffff',q);scTxt(c,'별을 삼킨 밤',240,160,14,'#ffe9a8',scCl((T-.6)*2));scCon(c,240,210,70,0,T,-1,'#c8a0ff',scCl((T-1)*2))}},
  {d:1600,lines:[['똑딱','가자, 하루! 첫 번째 별부터 되찾자!']],la:200,draw(c,T){scSky(c,T,'#03030c','#140c28',7,150);scCon(c,240,120,180,0,T,0);scHero(c,240,235,2,T)}}]}
function scSil(art){SC4.sil=SC4.sil||{};if(SC4.sil[art])return SC4.sil[art];const cv=document.createElement('canvas');cv.width=120;cv.height=104;const o=cv.getContext('2d');o.imageSmoothingEnabled=false;scBoss(o,art,60,100,1.6,{pulse:0});o.globalCompositeOperation='source-atop';o.fillStyle='#07060e';o.fillRect(0,0,120,104);return SC4.sil[art]=cv}
