function scGrad(o,a,b,c2){const g=o.createLinearGradient(0,0,0,SCH);g.addColorStop(0,a);g.addColorStop(.6,b);g.addColorStop(1,c2||b);o.fillStyle=g;o.fillRect(0,0,SCW,SCH)}
function scStars(o,r,n,col){for(let i=0;i<n;i++){o.globalAlpha=.3+r()*.7;o.fillStyle=r()<.15?(col||'#ffe9a8'):'#ffffff';const z=r()<.08?2:1;o.fillRect(Math.floor(r()*SCW),Math.floor(r()*SCH*.8),z,z)}o.globalAlpha=1}
