function scLocShot(k){const L=S4LOC[k],b=window.__S4[k];return {d:3000,on(){try{voice('bell',60+k*2,1.2,.025,audio.currentTime);voice('bell',67+k*2,1,.02,audio.currentTime+.3)}catch(e){}},draw(c,T){const z=1.12-scE(T/3)*.12;scCam(c,z,240,135+(1-scE(T/3))*10);L.paint(c,T);scCamOff(c);
  const q=scCl((T-.4)*1.5),n=Math.floor(scCl((T-.6)/1.2)*L.name.length);c.globalAlpha=.6*q;c.fillStyle='#000';c.fillRect(0,SCH-70,SCW,38);c.globalAlpha=1;c.fillStyle=b.c;c.fillRect(24,SCH-66,2,30);
  scTxt(c,'제 '+(k+1)+' 성  ·  ECLIPSE '+String(k+1).padStart(2,'0'),34,SCH-56,8,b.c,q,'left',700);scTxt(c,L.name.slice(0,n),34,SCH-40,15,'#ffffff',q,'left');scTxt(c,L.sub,34,SCH-28+2,8,'#c8c8e0',scCl((T-1.4)*2),'left',700)}}}
